import{_ as t,o as a,c as o,a2 as i}from"./chunks/framework.CFOYCmPM.js";const r="/dayz-studio/manual/images/dayz_studio_quests_view.png",p=JSON.parse('{"title":"Chapter 5: RPG Quests & Skyrim-Style Dialogue Trees","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quests-and-dialogue.md","filePath":"guide/quests-and-dialogue.md","lastUpdated":null}'),s={name:"guide/quests-and-dialogue.md"};function n(l,e,d,c,u,g){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="chapter-5-rpg-quests-skyrim-style-dialogue-trees" tabindex="-1">Chapter 5: RPG Quests &amp; Skyrim-Style Dialogue Trees <a class="header-anchor" href="#chapter-5-rpg-quests-skyrim-style-dialogue-trees" aria-label="Permalink to &quot;Chapter 5: RPG Quests &amp; Skyrim-Style Dialogue Trees&quot;">​</a></h1><p>DayZ Studio gives your server depth and purpose through immersive, branching quests. You can create cinematic dialogue scenes, prerequisite quest chains, and objective trackers with zero scripting.</p><hr><h2 id="⎇-the-quests-flow-editor-alt-4" tabindex="-1">⎇ The Quests Flow Editor (<code>Alt + 4</code>) <a class="header-anchor" href="#⎇-the-quests-flow-editor-alt-4" aria-label="Permalink to &quot;⎇ The Quests Flow Editor (`Alt + 4`)&quot;">​</a></h2><p><img src="'+r+'" alt="DayZ Studio Quest Flow Editor &amp; Node Graph"></p><hr><h2 id="💬-the-in-game-player-experience" tabindex="-1">💬 The In-Game Player Experience <a class="header-anchor" href="#💬-the-in-game-player-experience" aria-label="Permalink to &quot;💬 The In-Game Player Experience&quot;">​</a></h2><p>When a player approaches a quest-giver in-game:</p><ol><li>A dynamic prompt appears: <strong><code>[F] Talk to NPC</code></strong>.</li><li>Pressing <code>F</code> smoothly transitions the game camera into a close-up cinematic conversation perspective.</li><li>Dialogue text types out smoothly in a typewriter-style animation.</li><li>The player can select from 1 to 4 reply choices, ask questions, or decline the offer.</li></ol><hr><h2 id="🔒-branching-dialogue-conditions" tabindex="-1">🔒 Branching Dialogue &amp; Conditions <a class="header-anchor" href="#🔒-branching-dialogue-conditions" aria-label="Permalink to &quot;🔒 Branching Dialogue &amp; Conditions&quot;">​</a></h2><p>You can gate dialogue options behind specific survival criteria:</p><ul><li><strong>Held Item Check:</strong> Player must hold or carry an item (e.g., <code>Require: BloodBagFull</code>).</li><li><strong>Health / Medical State:</strong> Option only shows if player is <code>Bleeding</code>, <code>Sick</code>, or has <code>Health &lt; 50%</code>.</li><li><strong>Environmental Triggers:</strong> Option only appears during <code>Night</code>, <code>Rain</code>, or <code>Heavy Fog</code>.</li><li><strong>Faction Reputation:</strong> Option requires <code>Friendly with Survivors (Reputation &gt; 200)</code>.</li></ul><hr><h2 id="🎙️-adding-real-voice-lines" tabindex="-1">🎙️ Adding Real Voice Lines <a class="header-anchor" href="#🎙️-adding-real-voice-lines" aria-label="Permalink to &quot;🎙️ Adding Real Voice Lines&quot;">​</a></h2><p>Want your characters to speak with real audio?</p><ol><li>Record your dialogue lines and save them as <code>.ogg</code> or <code>.wav</code> files.</li><li>Select your dialogue node in DayZ Studio and click <strong>Attach Voice File</strong>.</li><li>DayZ Studio automatically organizes the audio files into <code>source/&lt;mod&gt;/sounds/</code> and generates the corresponding <code>CfgSoundShaders</code> and <code>CfgSoundSets</code> entries in <code>config.cpp</code>.</li></ol><hr><h2 id="🎯-quest-objective-nodes" tabindex="-1">🎯 Quest Objective Nodes <a class="header-anchor" href="#🎯-quest-objective-nodes" aria-label="Permalink to &quot;🎯 Quest Objective Nodes&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Objective Node</th><th style="text-align:left;">How It Works</th><th style="text-align:left;">HUD Compass Tracker</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Eliminate</strong></td><td style="text-align:left;">Tracks kills of specific infected, military zombies, wolves, bears, or bandit NPCs.</td><td style="text-align:left;"><code>Eliminate Infected: 4/10</code></td></tr><tr><td style="text-align:left;"><strong>Fetch / Deliver</strong></td><td style="text-align:left;">Requires bringing items (spark plugs, car batteries, canned food) to an NPC or container.</td><td style="text-align:left;"><code>Deliver Spark Plug to Viktor</code></td></tr><tr><td style="text-align:left;"><strong>Scout / Reach</strong></td><td style="text-align:left;">Player must travel to a marked location or beacon coordinate.</td><td style="text-align:left;"><code>Investigate Crash Site (240m)</code></td></tr><tr><td style="text-align:left;"><strong>Interact</strong></td><td style="text-align:left;">Requires using a generator, computer terminal, door lock, or medical kit.</td><td style="text-align:left;"><code>Power on Backup Generator</code></td></tr></tbody></table><hr><h2 id="🧭-in-game-quest-journal-compass-hud" tabindex="-1">🧭 In-Game Quest Journal &amp; Compass HUD <a class="header-anchor" href="#🧭-in-game-quest-journal-compass-hud" aria-label="Permalink to &quot;🧭 In-Game Quest Journal &amp; Compass HUD&quot;">​</a></h2><p>Players never have to guess what to do next:</p><ul><li><strong>Quest Journal (<code>J</code>):</strong> Pressing <code>J</code> opens an in-game quest journal displaying active objectives, lore descriptions, and completed accomplishments.</li><li><strong>Compass HUD Tracking (<code>T</code> or <code>Enter</code>):</strong> Track or untrack objectives to see distance markers and directional waypoints on the compass.</li><li><strong>Abandoning Quests (<code>A</code> twice):</strong> Double-tap <code>A</code> inside the journal to abandon active quests.</li></ul>',24)])])}const m=t(s,[["render",n]]);export{p as __pageData,m as default};
